         ("very slow", "very slowly, with space between the phrases")]


# ------------------------------------------------------------ THE CACHE
#
# A preview is the same request every time: the same voice, the same direction,
# the same fixed sentence. So the second person to press play on "angry" is
# asking a question that has already been answered, and answering it again costs
# one of ten requests that account has for the day.
#
# The key is the sha of the exact prompt and voice that were sent. Not of the
# label — the label is a name for a direction, and if that direction's WORDS are
# ever edited the audio must not still come back from the old key. Hashing what
# was actually sent makes the invalidation automatic and impossible to forget.
#
# It never expires. The same input gives the same output, so there is nothing
# for time to change.
PREVIEW_MODEL = "gemini-2.5-flash-preview-tts"


def preview_line(voice, label):
    """SAMPLE_PLAYER/Emotions.kt: the voice's own name and what it is doing.

    Short on purpose. Auditioning a voice across eight emotions is eight calls,
    and a long sentence makes that a minute of waiting to hear four seconds of
    difference. The name is in it so it is obvious which voice you are hearing."""
    for group, lab, glyph, text, spoken in EMOTIONS:
        if lab.lower() == (label or "").strip().lower():
            return "%s %s." % (voice, spoken)
    return "%s is speaking." % voice


def preview_key(voice, label):
    prompt, _, _ = compile_script("<PREVIEW: %s> %s" % (label, preview_line(voice, label)),
                                  [{"name": "PREVIEW", "voice": voice}])
    h = hashlib.sha256(("%s|%s|%s" % (PREVIEW_MODEL, voice, prompt)).encode()).hexdigest()[:20]
    return h, prompt


def preview_path(h):
    for ext in (".wav", ".mp3"):
        p = os.path.join(PREVIEWS, h + ext)
        if os.path.exists(p) and os.path.getsize(p) > 1000:
            return p
    return None


def preview(voice, label):
    """Cached, and it says which it was. A preview that quietly spends a request
    looks free, and the person finds out at the daily wall."""
    h, prompt = preview_key(voice, label)
    hit = preview_path(h)
    if hit:
        return {"ok": True, "file": os.path.basename(hit), "cached": True,
                "line": preview_line(voice, label)}

    def payload(_m):
        return {"contents": [{"parts": [{"text": prompt}]}],
                "generationConfig": {"responseModalities": ["AUDIO"], "speechConfig":
                    {"voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}}}}

    r = with_fallback([PREVIEW_MODEL] + [m for m in TTS_CHAIN if m != PREVIEW_MODEL], payload)
    if not r["ok"]:
        return r
    pcm = None
    for c in r["data"].get("candidates", []):
        for p in c.get("content", {}).get("parts", []):
            if "inlineData" in p:
                pcm = base64.b64decode(p["inlineData"]["data"])
    if not pcm:
        return {"ok": False, "error": "no audio in the reply"}
    os.makedirs(PREVIEWS, exist_ok=True)
    tmp = os.path.join(PREVIEWS, h + ".wav.new")
    secs = pcm_to_wav(tmp, pcm)
    os.replace(tmp, os.path.join(PREVIEWS, h + ".wav"))
    spend(r["label"], r["model"], n=0, audio_out=secs)
    return {"ok": True, "file": h + ".wav", "cached": False, "seconds": round(secs, 1),
            "key": r["label"], "line": preview_line(voice, label)}


def cache_state():
    n, b = 0, 0
    if os.path.isdir(PREVIEWS):
        for f in os.listdir(PREVIEWS):
            if f.endswith((".wav", ".mp3")):
                n += 1
                b += os.path.getsize(os.path.join(PREVIEWS, f))
    return {"count": n, "bytes": b}


def emotion_by_label(label):
    want = (label or "").strip().lower()
    for group, lab, glyph, text, spoken in EMOTIONS:
        if lab.lower() == want:
            return text
    return ""


TAG_RE = re.compile(r"<\s*([^<>:|]{1,30}?)\s*(?::\s*([^<>:|]{0,40}?))?\s*(?::\s*([^<>|]{0,30}?))?\s*>")


def compile_script(text, speakers):
    """Turn a tagged script into what Gemini is actually sent.

    THE TAG, invented here because Gemini has nothing like Hume's per-utterance
    `description` field. Hume takes an acting direction beside every line. Gemini
    takes ONE prose direction for the whole call, and a speaker name in front of
    each line. So the tags are compiled rather than passed through.

        <Viveka>                  this line is Viveka's
        <Viveka: Weary>           and he is weary
        <Viveka: Weary: slow>     and slow with it
        <Manan>                   now Manan

    Angle brackets because they cannot be typed by accident in dialogue the way a
    bracket or a slash can, and because the person is already reading a script
    where a name means a speaker.

    Returns (prompt, speakers_used, problems). PROBLEMS ARE NEVER SILENT: a tag
    naming somebody with no voice would otherwise come back as a line read in the
    wrong voice, which sounds like a bad model rather than a typo.
    """
    names = [s.get("name", "").strip() for s in speakers if s.get("name", "").strip()]
    known = {n.lower(): n for n in names}
    problems = []
    lines = []
    cur = names[0] if names else ""
    pending = ""
    pos = 0
    for m in TAG_RE.finditer(text or ""):
        chunk = (text[pos:m.start()] or "").strip()
        if chunk:
            lines.append((cur, pending, chunk))
            pending = ""
        who = (m.group(1) or "").strip()
        if who.lower() in known:
            cur = known[who.lower()]
        else:
            problems.append("no voice is set for <%s>" % who)
        emo = (m.group(2) or "").strip()
        pace = (m.group(3) or "").strip()
        bits = []
        if emo:
            d = emotion_by_label(emo)
            if not d:
                problems.append("no direction called %s" % emo)
            bits.append(d or emo)
        if pace:
            p = dict(PACES).get(pace.lower(), pace)
            if p:
                bits.append(p)
        pending = ", ".join(bits)
        pos = m.end()
    tail = (text[pos:] or "").strip()
    if tail:
        lines.append((cur, pending, tail))

    used = [n for n in names if any(l[0] == n for l in lines)] or names[:1]
    if len(used) > 2:
        problems.append("Gemini takes two speakers in one call and this has %d" % len(used))
        used = used[:2]

    head = []
    if len(used) > 1:
        head.append("TTS the following conversation between %s." % " and ".join(used))
    else:
        head.append("Read the following aloud.")
    for s in speakers:
        n = s.get("name", "").strip()
        if n in used:
            head.append("%s is a %s voice."
                        % (n, VOICE_TIMBRE.get(s.get("voice", ""), "clear")))
    head.append("Follow the direction in brackets before each line "
                "and do not read the brackets aloud.")

    body = []
    for who, direction, said in lines:
        prefix = ("%s: " % who) if len(used) > 1 else ""
        body.append(prefix + (("(%s) " % direction) if direction else "") + said)
    return "\n".join(head) + "\n\n" + "\n".join(body), used, problems


def speak(text, voice, voice2=None, name_a="A", name_b="B"):
    def payload(_model):
        if voice2:
            sc = {"multiSpeakerVoiceConfig": {"speakerVoiceConfigs": [
                {"speaker": name_a, "voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}},
                {"speaker": name_b, "voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice2}}}]}}
        else:
            sc = {"voiceConfig": {"prebuiltVoiceConfig": {"voiceName": voice}}}
        return {"contents": [{"parts": [{"text": text}]}],
                "generationConfig": {"responseModalities": ["AUDIO"], "speechConfig": sc}}

    r = with_fallback(TTS_CHAIN, payload)
    if not r["ok"]:
        return r
    pcm = None
    for c in r["data"].get("candidates", []):
        for p in c.get("content", {}).get("parts", []):
            if "inlineData" in p:
                pcm = base64.b64decode(p["inlineData"]["data"])
    if not pcm:
        return {"ok": False, "error": "no audio in the reply", "log": r["log"]}
    os.makedirs(OUTDIR, exist_ok=True)
    fname = "speak_%s.wav" % time.strftime("%Y%m%d_%H%M%S")
    secs = pcm_to_wav(os.path.join(OUTDIR, fname), pcm)
    spend(r["label"], r["model"], n=0, audio_out=secs)
    return {"ok": True, "file": fname, "seconds": round(secs, 1),
            "voice": voice, "model": r["model"], "key": r["label"], "log": r["log"]}


# ------------------------------------------------------------------ LISTEN

MIME = {".mp3": "audio/mp3", ".wav": "audio/wav", ".flac": "audio/flac",
        ".ogg": "audio/ogg", ".m4a": "audio/mp4", ".aac": "audio/aac",
        ".aiff": "audio/aiff"}


# --------------------------------------------------- audioprep, ported whole
#
# From MAHA_TRANSCRIBE_TERMUX_TERMINAL/audioprep.py, target and reasoning kept:
#
#     24 kHz, mono, Opus, 48 kbps, "audio" tuning
#
# THE TARGET MOVED, and the reason is the engine. Upstream aimed at 16 kHz and
# 32 kbps voip because AssemblyAI resamples to 16 kHz internally and is billed
# per second, so bytes above that were pure waste.
#
# Gemini is billed the same way — MEASURED: audio input is exactly 25 tokens a
# second, whatever the bitrate — so a bigger file costs nothing but the seconds
# it takes to upload over loopback. The thing that WAS being paid for at 16/32
# was intelligibility: voip tuning is built to keep a phone call understandable
# to a human ear, and it thins exactly the high-frequency detail that separates
# an s from an f, a t from a k. That is free to keep here, so it is kept.
#
# 24 kHz because it holds everything up to 12 kHz, which covers the fricatives
# 16 kHz starts to lose. 48 kbps because Opus is transparent for speech there.
# "audio" rather than "voip" because voip's job is a human listener on a bad
# line, and the listener here is a model that was trained on clean speech.
#
# A two-hour phone video still becomes a same-length mono file well under 40 MB.
PREP_RATE = 24000
PREP_BITRATE = "48k"
PREP_TIMEOUT = 900        # a backstop against a corrupt file that hangs ffmpeg
MAX_UPLOAD_BYTES = 2 * 1024 * 1024 * 1024


class AudioPrepError(Exception):
    """Raised with a message safe to show to the person as it is."""


def ffmpeg_bin():
    import shutil
    return shutil.which("ffmpeg")


def probe_duration(path):
    """Seconds, or None. Never raises: a duration is not worth a failure."""
    import shutil
    ffprobe = shutil.which("ffprobe")
    if not ffprobe:
        return None
    try:
        out = subprocess.run([ffprobe, "-v", "error", "-show_entries",
                              "format=duration", "-of",
                              "default=noprint_wrappers=1:nokey=1", path],
                             capture_output=True, text=True, timeout=30)
        return float(out.stdout.strip())
    except Exception:
        return None


def optimize_audio(input_bytes, original_name=""):
    import shutil
    ff = ffmpeg_bin()
    if not ff:
        raise AudioPrepError(
            "ffmpeg is not installed on this machine, so audio cannot be "
            "optimized and video cannot be read. Termux `pkg install ffmpeg`, "
            "macOS `brew install ffmpeg`.")
    if len(input_bytes) > MAX_UPLOAD_BYTES:
        raise AudioPrepError("that file is %.0f MB, over the %d MB limit."
                             % (len(input_bytes) / 1048576.0,
                                MAX_UPLOAD_BYTES // 1048576))
    suffix = os.path.splitext(original_name)[1][:8] if original_name else ""
    if not suffix or any(c in suffix for c in ("/", "\\", "\x00")):
        suffix = ".input"
    workdir = tempfile.mkdtemp(prefix="gttprep_")
    in_path = os.path.join(workdir, "in" + suffix)
    out_path = os.path.join(workdir, "out.ogg")
    try:
        with open(in_path, "wb") as fh:
            fh.write(input_bytes)
        duration = probe_duration(in_path)
        t0 = time.time()
        proc = subprocess.run(
            [ff, "-y", "-i", in_path, "-vn", "-ac", "1", "-ar", str(PREP_RATE),
             "-c:a", "libopus", "-b:a", PREP_BITRATE, "-application", "audio",
             "-f", "ogg", out_path],
            capture_output=True, text=True, timeout=PREP_TIMEOUT)
        took = time.time() - t0
        if proc.returncode != 0 or not os.path.exists(out_path):
            # prefer the line that names the problem with the INPUT: "invalid
            # data found" is far more useful than "error opening output files",
            # which is what ffmpeg says about the same failure from the far end
            lines = [l.strip() for l in (proc.stderr or "").splitlines() if l.strip()]
            reason = next((l for l in reversed(lines)
                           if "invalid data found" in l.lower()
                           or "error opening input" in l.lower()
                           or "does not contain any stream" in l.lower()
                           or "moov atom not found" in l.lower()),
                          lines[-1] if lines else "unknown ffmpeg error")
            raise AudioPrepError("could not read that file as audio or video: %s" % reason)
        out_bytes = open(out_path, "rb").read()
        if not out_bytes:
            raise AudioPrepError("the conversion produced an empty file, the "
                                 "source may have no audio track.")
        return out_bytes, {"original_bytes": len(input_bytes),
                           "optimized_bytes": len(out_bytes),
                           "duration_seconds": duration,
                           "convert_seconds": round(took, 2)}
    except subprocess.TimeoutExpired:
        raise AudioPrepError("conversion did not finish within %ds, the file may "
                             "be corrupt or unusually long." % PREP_TIMEOUT)
    finally:
        shutil.rmtree(workdir, ignore_errors=True)


def have_ffmpeg():
    try:
        subprocess.run(["ffmpeg", "-version"], capture_output=True, timeout=10)
        return True
    except Exception:
        return False


def to_supported(path):
    """Gemini takes wav mp3 flac ogg aac aiff. Anything else, and anything the
    browser recorded, goes through ffmpeg. Mono 16k flac keeps it small."""
    ext = os.path.splitext(path)[1].lower()
    if ext in MIME and ext != ".wav":
        return path, MIME[ext], 0
    if not have_ffmpeg():
        if ext in MIME:
            return path, MIME[ext], 0
        return None, None, 0
    out = tempfile.mktemp(suffix=".flac")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-y", "-i", path,
                    "-ar", "16000", "-ac", "1", "-map", "0:a", "-c:a", "flac", out],
                   capture_output=True, timeout=600)
    if not os.path.exists(out):
        return None, None, 0
    secs = 0.0
    try:
        p = subprocess.run(["ffprobe", "-v", "error", "-show_entries",
                            "format=duration", "-of", "csv=p=0", out],
                           capture_output=True, timeout=60)
        secs = float(p.stdout.decode().strip() or 0)
    except Exception:
        pass
    return out, "audio/flac", secs


def listen(path, language="", verbatim=True):
    conv, mime, secs = to_supported(path)
    if not conv:
        return {"ok": False, "error": "cannot read that file, and no ffmpeg to convert it"}
    b = base64.b64encode(open(conv, "rb").read()).decode()
    ask = "Transcribe this audio. Output only the transcript, nothing else."
    if verbatim:
        ask += " Keep it verbatim, including false starts."
    if language:
        ask += " The language is %s." % language

    def payload(_m):
        return {"contents": [{"parts": [{"text": ask},
                                        {"inlineData": {"mimeType": mime, "data": b}}]}]}

    r = with_fallback(STT_CHAIN, payload)
    if not r["ok"]:
        return r
    text = "".join(p.get("text", "") for c in r["data"].get("candidates", [])
                   for p in c.get("content", {}).get("parts", []))
    um = r["data"].get("usageMetadata", {})
    audio_tokens = 0
    for det in um.get("promptTokensDetails", []):
        if det.get("modality") == "AUDIO":
            audio_tokens = det.get("tokenCount", 0)
    heard = audio_tokens / 25.0 if audio_tokens else secs   # 25 tokens a second, measured
    spend(r["label"], r["model"], n=0, audio_in=heard)
    return {"ok": True, "text": text.strip(), "seconds": round(heard, 1),
            "model": r["model"], "key": r["label"], "log": r["log"]}


# -------------------------------------------------------------------- KEYS

# A key is one of five things and they are not interchangeable. Calling "no
# credit" working sends the ring at a wall; calling it refused has somebody
# delete a live account they only needed to top up. Ported from
# modules/keyring.md 2d and 2e, including the order the tests run in.
#
#   working   it did the work                       use it
#   busy      throttled this minute                 wait, NEVER delete
#   no credit real key, live account, no money      top up, or delete on purpose
#   refused   wrong, revoked, wrong provider        delete
#   unknown   the answer says nothing about the key  try again, never delete
RETRY_HINT = re.compile(r"retrydelay|retry-after|retryinfo|quotafailure|"
                        r"per minute|try again in", re.I)
MONEY_STRONG = re.compile(r"credit|balance|depleted|insufficient|billing|"
                          r"payment|prepayment|e0300|zero_credits", re.I)


WHY = {"working": "valid, and it did real work",
       "busy": "throttled right now, which says nothing about the key",
       "no credit": "the account is alive and has no money in it",
       "refused": "revoked, mistyped, or not a Gemini key",
       "unknown": "no answer about the key itself, try again"}


def verdict_for(code, body):
    """The provider's answer, in one word. A pure function, so it can be tested
    without a key and without a network."""
    b = body if isinstance(body, str) else ""
    if code == 200:
        return "working"
    if code in (401, 403):
        return "refused"
    if code == 429:
        # THE RETRY HINT IS CHECKED FIRST AND WINS. Google answers a spent
        # account and an impatient one with the same status and the same word,
        # so matching on "quota" alone tells somebody to delete a live key
        # because they pressed Test twice in one second.
        if RETRY_HINT.search(b):
            return "busy"
        if MONEY_STRONG.search(b):
            return "no credit"
        return "busy"
    if code == 404:
        return "unknown"          # the model is gone, which says nothing about the key
    if code in (500, 502, 503, 504) or code < 0:
        return "unknown"
    return "unknown"


DELETABLE = ("refused",)          # and "no credit", but only when asked by name


def remove_keys(labels, reason="removed"):
    """Take keys out of the ring and put them where they can be fetched back.

    A permanent condemnation that cannot be undone is a bug wearing a rule's
    clothing, so nothing is destroyed: the entries move to a graveyard file,
    also chmod 600, and Put back returns them. The ring is rewritten whole here
    rather than appended to, which is the one operation that has to be, and it
    goes through a .new file and a rename like everything else."""
    ring = load_ring()
    keep = [(l, k) for l, k in ring if l not in labels]
    gone = [(l, k) for l, k in ring if l in labels]
    if not gone:
        return {"ok": True, "removed": [], "ring": len(ring)}
    head = ""
    if os.path.exists(KEYFILE):
        for line in open(KEYFILE).read().splitlines():
            if line.strip().startswith("#"):
                head += line + "\n"
            elif line.strip():
                break
    body = "".join("%s\n%s\n\n" % (l, k) for l, k in keep)
    tmp = KEYFILE + ".new"
    with open(tmp, "w") as f:
        f.write((head + "\n" if head else "") + body)
    os.chmod(tmp, 0o600)
    os.replace(tmp, KEYFILE)
    os.chmod(KEYFILE, 0o600)

    os.makedirs(HOME, exist_ok=True)
    with open(GRAVEYARD, "a") as f:
        for l, k in gone:
            f.write("# %s, %s\n%s\n%s\n\n" % (reason, time.strftime("%d.%m.%Y %H:%M"), l, k))
    os.chmod(GRAVEYARD, 0o600)
    return {"ok": True, "removed": [{"label": l, "masked": mask(k)} for l, k in gone],
            "ring": len(load_ring())}


def removed_keys():
    if not os.path.exists(GRAVEYARD):
        return []
    lines = [l.rstrip() for l in open(GRAVEYARD).read().splitlines()]
    out, i = [], 0
    while i < len(lines) - 1:
        if lines[i] and not lines[i].startswith("#") and KEY_RE.fullmatch(lines[i + 1].strip()):
            out.append((lines[i], lines[i + 1].strip()))
            i += 2
        else:
            i += 1
    return out


def restore_keys():
    """Put everything back and empty the graveyard. import_keys does the
    merging, so a key that is somehow already in the ring is not doubled."""
    gone = removed_keys()
    if not gone:
        return {"ok": True, "restored": [], "ring": len(load_ring())}
    text = "".join("%s\n%s\n\n" % (l, k) for l, k in gone)
    r = import_keys(text, "put back")
    open(GRAVEYARD, "w").close()
    return {"ok": True, "restored": r["added"], "ring": r["ring"]}


# =========================================================================
# THE CHUNKING SENDING ALGORITHM
#
# Baba, 5.9.2026: "if I'm uploading you 5 hours of audio, you will not send
# 5 hours at once. Break it in chunks of 10 minutes, but break it at a point
# where the silence is, not in the middle of the waveform. Then send, transcribe,
# put it in the box, save it in archive so it's not lost even if my battery runs
# out. Between the sessions keep the same state."
#
# Four rules, and each one is there for a reason that has already cost
# somebody something:
#
#   1  CUT AT SILENCE, NOT AT THE CLOCK. A cut through a word gives two
#      halves that are each unintelligible, and the model does not tell you
#      that: it invents a plausible word at both edges. Ten minutes is where
#      to LOOK for a cut, not where to make one.
#
#   2  THE FILE GOES TO DISK FIRST. You cannot find silence in something you
#      are streaming past. This is exactly why it cannot be done for live
#      recording, and why live recording keeps its own segmenting.
#
#   3  SAVE AFTER EVERY PART. A five-hour file is an hour of transcribing on
#      a phone. Batteries die. Anything held only in a browser tab is gone,
#      so each part's text is written to disk the moment it comes back.
#
#   4  RESUME IS THE DEFAULT, NOT A FEATURE. On start the server looks for
#      unfinished jobs and picks them up. A job that needs a person to
#      remember to resume it is a job that gets abandoned.
CHUNK_TARGET = 600.0        # ten minutes, the place to start looking
CHUNK_SEARCH = 150.0        # how far either side a silence may be, two and a half minutes
CHUNK_MIN = 120.0           # never make a part shorter than this
SILENCE_DB = "-32dB"        # quieter than this counts as silence
SILENCE_MIN = 0.55          # and it has to last this long to be a pause


def silence_points(path):
    """Where the pauses are, in seconds. ffmpeg's silencedetect writes them to
    stderr as a side effect of decoding, so this reads the log rather than the
    output. Returns the MIDDLE of each pause, which is the safest place to cut:
    the edges still carry the tail of a word and the breath before the next."""
    ff = ffmpeg_bin()
    if not ff:
        return []
    try:
        p = subprocess.run(
            [ff, "-hide_banner", "-nostats", "-i", path,
             "-af", "silencedetect=noise=%s:d=%s" % (SILENCE_DB, SILENCE_MIN),
             "-f", "null", "-"],
            capture_output=True, text=True, timeout=PREP_TIMEOUT)
    except Exception:
        return []
    starts, mids = [], []
    for line in (p.stderr or "").splitlines():
        if "silence_start:" in line:
            try:
                starts.append(float(line.split("silence_start:")[1].strip().split()[0]))
            except Exception:
                pass
        elif "silence_end:" in line:
            try:
                end = float(line.split("silence_end:")[1].strip().split()[0])
            except Exception:
                continue
            if starts:
                mids.append(round((starts.pop() + end) / 2.0, 2))
    return sorted(mids)


def plan_cuts(duration, points, target=CHUNK_TARGET, search=CHUNK_SEARCH, minimum=CHUNK_MIN):
    """Where to cut. A pure function, so it can be tested without ffmpeg.

    Walks forward from the last cut: the next one wants to land `target`
    seconds along, and takes the pause nearest to that within `search`. If
    there is no pause in that window — a lecture with no breath in it, music
    under speech — it cuts at the clock and says so by simply doing it, because
    a part that is fifteen minutes long is worse than one clean cut in a
    sentence."""
    if duration <= 0:
        return []
    if duration <= target + search:
        return []                       # one part, no cuts at all
    cuts, at = [], 0.0
    while duration - at > target + search:
        want = at + target
        window = [p for p in points
                  if abs(p - want) <= search and p - at >= minimum and duration - p >= minimum]
        cut = min(window, key=lambda p: abs(p - want)) if window else want
        if cut <= at + minimum:
            cut = at + target
        cuts.append(round(cut, 2))
        at = cut
    return cuts


def cut_points_to_parts(duration, cuts):
    """[(start, end)] covering the whole thing, in order, nothing dropped."""
    edges = [0.0] + list(cuts) + [duration]
    return [(edges[i], edges[i + 1]) for i in range(len(edges) - 1)]


# ------------------------------------------------------------------- jobs
JOBS = os.path.join(HOME, "jobs")
_job_lock = threading.Lock()


def job_dir(jid):
    return os.path.join(JOBS, jid)


def job_read(jid):
    p = os.path.join(job_dir(jid), "job.json")
    if not os.path.exists(p):
        return None
    try:
        return json.load(open(p))
    except Exception:
        return None


def job_write(job):
    """Written after every single part. This is rule 3, and it is the whole
    reason a five hour file survives a flat battery."""
    d = job_dir(job["id"])
    os.makedirs(d, exist_ok=True)
    tmp = os.path.join(d, "job.json.new")
    with open(tmp, "w") as f:
        json.dump(job, f, indent=1)
    os.replace(tmp, os.path.join(d, "job.json"))


def job_list():
    out = []
    if not os.path.isdir(JOBS):
        return out
    for jid in sorted(os.listdir(JOBS)):
        j = job_read(jid)
        if j:
            out.append({k: j[k] for k in ("id", "name", "state", "done", "total",
                                          "started", "duration") if k in j})
    return out


def job_text(job):
    return "\n\n".join(t for t in job.get("texts", []) if t)


def start_chunk_job(raw, name):
    """Take a file, put it on disk, find the pauses, cut it, and start."""
    jid = time.strftime("%Y%m%d_%H%M%S")
    d = job_dir(jid)
    os.makedirs(d, exist_ok=True)
    src = os.path.join(d, "source" + (os.path.splitext(name)[1][:8] or ".input"))
    with open(src, "wb") as f:
        f.write(raw)

    duration = probe_duration(src) or 0.0
    points = silence_points(src)
    cuts = plan_cuts(duration, points)
    spans = cut_points_to_parts(duration, cuts)

    job = {"id": jid, "name": name or "audio", "state": "cutting",
           "duration": round(duration, 1), "silences": len(points),
           "total": len(spans), "done": 0, "texts": [], "parts": [],
           "started": time.time(), "note": ""}
    job_write(job)

    ff = ffmpeg_bin()
    parts = []
    for i, (a, b) in enumerate(spans):
        out = os.path.join(d, "part_%03d.ogg" % (i + 1))
        subprocess.run([ff, "-y", "-i", src, "-ss", "%.2f" % a, "-to", "%.2f" % b,
                        "-vn", "-ac", "1", "-ar", str(PREP_RATE), "-c:a", "libopus",
                        "-b:a", PREP_BITRATE, "-application", "audio", "-f", "ogg", out],
                       capture_output=True, timeout=PREP_TIMEOUT)
        parts.append({"file": os.path.basename(out), "start": round(a, 2),
                      "end": round(b, 2), "seconds": round(b - a, 1),
                      "at_silence": bool(i < len(cuts) and cuts[i] in points)})
    job["parts"] = parts
    job["state"] = "running"
    job_write(job)
    try:
        os.remove(src)          # the parts are the work now; the original is bytes
    except Exception:
        pass
    run_chunk_job(jid)
    return job


def run_chunk_job(jid):
    """One part at a time, in order, saving after each. Never two at once: the
    parts belong to one recording and the daily budget is small enough that
    racing them only means racing to the wall."""
    def worker():
        while True:
            with _job_lock:
                job = job_read(jid)
                if not job or job["state"] not in ("running",):
                    return
                i = job["done"]
                if i >= job["total"]:
                    job["state"] = "finished"
                    job_write(job)
                    return
            part = job["parts"][i]
            path = os.path.join(job_dir(jid), part["file"])
            r = listen(path, job.get("lang", "")) if os.path.exists(path) else \
                {"ok": False, "error": "part %d is missing" % (i + 1)}
            with _job_lock:
                job = job_read(jid) or job
                if r.get("ok"):
                    job["texts"] = job.get("texts", []) + [r.get("text", "")]
                    job["done"] = i + 1
                    job["note"] = "part %d of %d, %s on [%s]" % (
                        i + 1, job["total"], r.get("model", ""), r.get("key", ""))
                else:
                    job["state"] = "stalled"
                    job["note"] = r.get("error", "that part did not go through")
                job_write(job)
            if job["state"] != "running":
                return
    threading.Thread(target=worker, daemon=True).start()


def resume_jobs():
    """Rule 4. On start, anything left running is picked up where it stopped.
    A job that needs somebody to remember to resume it is a job that gets
    abandoned, and this one is five hours long."""
    n = 0
    for j in job_list():
        if j.get("state") == "running":
            run_chunk_job(j["id"])
            n += 1
    return n


def health():
    """What is installed and what is not. The Keys tab shows this so a missing
    ffmpeg is discovered here rather than by a transcription that fails."""
    import shutil
    def mod(name):
        try:
            __import__(name)
            return True
        except Exception:
            return False
    return {"python": "%d.%d.%d" % sys.version_info[:3],
            "flask": mod("flask"),
            "waitress": mod("waitress"),
            "ffmpeg": bool(shutil.which("ffmpeg")),
            "keyfile": KEYFILE,
            "keys": len(load_ring()),
            "outdir": OUTDIR,
            "version": VERSION}


def test_all_keys():
    """One real call per key, the cheapest model with the most daily room.

    modules/gemini.md: a GET on /models returns 200 for an account with zero
    credit, so it tests validity only. The only way to learn whether an account
    can do work is to ask it to do some."""
    ring = load_ring()
    rows, lock = [], threading.Lock()

    def check(pair):
        label, key = pair
        t0 = time.time()
        code, body = post("gemini-3.1-flash-lite", "generateContent",
                          {"contents": [{"parts": [{"text": "hi"}]}]}, key, timeout=60)
        if code in (503, 500, 502, 504):
            time.sleep(2)                     # busy model, not a bad key
            code, body = post("gemini-3.1-flash-lite", "generateContent",
                              {"contents": [{"parts": [{"text": "hi"}]}]}, key, timeout=60)
        ms = int((time.time() - t0) * 1000)
        v = verdict_for(code, body if isinstance(body, str) else "")
        why = WHY[v]
        if v == "working":
            spend(label, "gemini-3.1-flash-lite")
        elif v == "no credit":
            mark_dead(label, "no credit")
        elif v == "refused":
            mark_dead(label, "refused")
        elif v == "busy":
            q = read_quota(body if isinstance(body, str) else "")
            if q.get("rpd"):
                why = "at its daily wall on this model (%d a day)" % q["rpd"]
        with lock:
            rows.append({"label": label, "masked": mask(key), "verdict": v,
                         "why": why, "ms": ms, "code": code})

    ts = [threading.Thread(target=check, args=(p,)) for p in ring]
    for th in ts:
        th.start()
    for th in ts:
        th.join()
    order = {"working": 0, "busy": 1, "no credit": 2, "unknown": 3, "refused": 4}
    rows.sort(key=lambda r: (order.get(r["verdict"], 9), r["label"]))
    return rows


def test_one_key(label):
    """Test a single account. The Key Tester puts test on every row, because
    the question is usually about one account and retesting twenty to answer it
    spends nineteen requests for nothing."""
    for l, key in load_ring():
        if l != label:
            continue
        t0 = time.time()
        code, body = post("gemini-3.1-flash-lite", "generateContent",
                          {"contents": [{"parts": [{"text": "hi"}]}]}, key, timeout=60)
        v = verdict_for(code, body if isinstance(body, str) else "")
        if v == "working":
            spend(label, "gemini-3.1-flash-lite")
        return {"ok": True, "label": label, "masked": mask(key), "verdict": v,
                "why": WHY[v], "ms": int((time.time() - t0) * 1000), "code": code}
    return {"ok": False, "error": "no account called %r" % label}


def models_for(label):
    """What this account can reach. GET /models answers 200 for an account with
    zero credit, so this says nothing about money — it is the catalogue, and it
    is worth seeing when a model name stops working."""
    for l, key in load_ring():
        if l != label:
            continue
        req = urllib.request.Request(
            "https://generativelanguage.googleapis.com/v1beta/models?pageSize=1000",
            headers={"x-goog-api-key": key})
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                d = json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            return {"ok": False, "error": "the account answered %d" % e.code}
        except Exception as ex:
            return {"ok": False, "error": str(ex)[:120]}
        names = [m["name"].replace("models/", "") for m in d.get("models", [])]
        return {"ok": True, "label": label, "count": len(names),
                "tts": [n for n in names if "tts" in n],
                "image": [n for n in names if "image" in n or "banana" in n],
                "text": [n for n in names if "flash" in n or "pro" in n or "gemma" in n][:14],
                "all": names}
    return {"ok": False, "error": "no account called %r" % label}


REWRITE_PROMPTS = {
    "grammar": ("Correct only the grammar, spelling and punctuation of the text below. "
                "Do not rephrase, do not rearrange or merge sentences, do not change the "
                "wording, structure or shape of the text in any way. Make only the smallest "
                "necessary fixes. Keep the original language. Reply with the corrected text "
                "only, nothing else.\n\nText:\n"),
    "reshape": ("Rewrite the text below so it flows well. Remove every repetition and merge "
                "everything into one clear text that explains the whole message. You may "
                "rearrange sentences freely. Write exactly as a human would. Do not use "
                "dashes, bullet points, headings or any special formatting, only plain "
                "sentences with normal punctuation. Keep the length balanced and the tone "
                "friendly but clear. Keep the original language. Reply with the rewritten "
                "text only, nothing else.\n\nText:\n"),
}


def rewrite(kind, text):
    """Correct or reshape a transcript. THE MODEL IS NOT A SETTING.

    modules/model-names.md: a dated model string is a time bomb — it fails with
    not_found before the request runs, so it never appears in usage and looks
    exactly like a dead key. So there is no model picker and no dated name in
    the page: the chain here is tried in order and the first one that answers
    wins, exactly as Speak and Listen already work."""
    prompt = REWRITE_PROMPTS.get(kind, REWRITE_PROMPTS["grammar"]) + (text or "")

    def payload(_m):
        return {"contents": [{"parts": [{"text": prompt}]}]}

    r = with_fallback(STT_CHAIN, payload)
    if not r["ok"]:
        return r
    out = "".join(p.get("text", "") for c in r["data"].get("candidates", [])
                  for p in c.get("content", {}).get("parts", []))
    return {"ok": True, "text": out.strip(), "model": r["model"], "key": r["label"]}


def budget():
    """What is left today, in requests and in hours."""
    d = read_ledger()
    ring = [(l, k) for l, k in load_ring() if l not in d["dead"]]
    out = {"keys_live": len(ring), "models": [], "day": d["day"],
           "reset_in": seconds_to_reset(),
           "audio_out": round(d["audio_out"], 1), "audio_in": round(d["audio_in"], 1)}
    for model, meta in LIMITS.items():
        cap = limit_for(model, "rpd")
        used = sum(v for k, v in d["spend"].items() if k.endswith("|" + model))
        total = cap * len(ring)
        out["models"].append({
            "model": model, "use": meta["use"], "rpm": limit_for(model, "rpm"),
            "rpd": cap, "measured": meta["rpd"] is not None,
            "total": total, "used": used, "left": max(total - used, 0)})
    out["ledger_only"] = True   # counts what this app spent, not what other tools spent
    tts_left = sum(m["left"] for m in out["models"] if m["use"] == "tts")
    stt_left = sum(m["left"] for m in out["models"] if m["use"] == "stt")
    # 8 minutes is the measured per-request ceiling; 2 minutes is a normal take
    out["speak_hours_max"] = round(tts_left * 8 / 60.0, 1)
    out["speak_hours_real"] = round(tts_left * 2 / 60.0, 1)
    # one STT call can hold about 11 hours of audio in a 1M context window
    out["listen_hours_max"] = round(stt_left * 11, 1)
    out["listen_hours_real"] = round(stt_left * 0.25, 1)
    return out


# ------------------------------------------------------------------- tests

def run_tests():
    print("GOOGLE TTS AND STT v%d, four tests, real keys" % VERSION)

    # Running four provider tests against an empty ring produces four failures
    # that all mean one thing, and none of them says what that thing is. Say it
    # once, here, and stop.
    if not load_ring():
        print("\n  The key ring is empty, so there is nothing to test.")
        print("  %s holds no keys." % KEYFILE)
        print("\n  Give it your key file, in whatever shape it was saved:")
        print("      gtt import /sdcard/Download/your-keys.txt")
        print("\n  A note, a .env, a JSON export, a CSV, a markdown table: it")
        print("  finds the keys itself and never adds one twice.\n")
        return 1

    ok = 0
    print("1. key ring parses and at least one key is live")
    rows = test_all_keys()
    live = [r for r in rows if r["verdict"] in ("working", "busy")]
    for r in rows:
        print("   %-14s %-9s %s" % (r["label"], r["verdict"], r["why"]))
    print("   %d live of %d" % (len(live), len(rows)))
    ok += 1 if live else 0

    print("2. Speak makes audio")
    r = speak("Say plainly: the fuel is still there.", "Charon")
    if r.get("ok"):
        print("   %s  %.1fs  via %s on [%s]" % (r["file"], r["seconds"], r["model"], r["key"]))
    else:
        print("   FAILED %s %s" % (r.get("error"), r.get("log")))
    ok += 1 if r.get("ok") and r["seconds"] > 0.5 else 0

    print("3. Listen reads that audio back")
    t = {}
    if r.get("ok"):
        t = listen(os.path.join(OUTDIR, r["file"]))
        if t.get("ok"):
            print("   heard: %r via %s on [%s]" % (t["text"][:60], t["model"], t["key"]))
        else:
            print("   FAILED %s %s" % (t.get("error"), t.get("log")))
    ok += 1 if t.get("ok") and "fuel" in t.get("text", "").lower() else 0

    print("4. the ledger counted it and knows when it resets")
    b = budget()
    h = b["reset_in"] // 3600
    print("   day %s, resets in %dh%02dm" % (b["day"], h, (b["reset_in"] % 3600) // 60))
    for m in b["models"]:
        star = "" if m["measured"] else "  (rpd assumed, never reached)"
        print("   %-30s %4d of %4d left today%s" % (m["model"], m["left"], m["total"], star))
    print("   speak: up to %.1f h today, realistically %.1f h" % (b["speak_hours_max"], b["speak_hours_real"]))
    print("   listen: %d calls left, and one call holds about 11 h of audio" %
          sum(m["left"] for m in b["models"] if m["use"] == "stt"))
    ok += 1 if b["models"] and b["reset_in"] > 0 else 0

    print("\n%d of 4 green" % ok)
    return 0 if ok == 4 else 1


# --------------------------------------------------------------------- web

PAGE = '<!doctype html><html lang="en"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Google TTS and STT</title><style>\n:root{\n --bg:#0b0d10; --surface:#0d1117; --surface-2:#141a21; --line:#23303d;\n --amber:#f59e0b; --amber-hi:#fbbf24;\n --prose:#f2ddb4; --dim:#8a7a5c;\n --red:#ef4444; --green:#22c55e; --coral:#d97757; --grey:#6b655c;\n --mono:ui-monospace,"JetBrains Mono","Cascadia Mono","SF Mono",Menlo,Consolas,monospace;\n}\n*{box-sizing:border-box}\n*:focus-visible{outline:2px solid var(--amber);outline-offset:2px}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important}}\nhtml,body{margin:0;background:var(--bg);color:var(--prose);font-family:var(--mono);min-height:100vh}\nbody{display:flex;justify-content:center;align-items:flex-start;\n padding:calc(10px + env(safe-area-inset-top)) 8px calc(14px + env(safe-area-inset-bottom))}\n.unit{width:100%;max-width:640px;background:var(--surface);border:1px solid var(--line);\n border-radius:10px;padding:12px}\n.top{display:flex;gap:6px;align-items:center;margin-bottom:10px}\n.tabs{display:flex;gap:3px;flex:1}\n.tab-btn{flex:1;background:var(--surface-2);border:1px solid var(--line);color:var(--dim);\n font-family:var(--mono);font-size:11px;letter-spacing:.06em;padding:14px 6px;border-radius:999px;\n cursor:pointer}\n.tab-btn.active{color:var(--bg);background:var(--amber);border-color:var(--amber);font-weight:700}\n.cog{flex:0 0 auto;width:44px;height:44px;border-radius:50%;background:var(--surface-2);\n border:1px solid var(--line);color:var(--amber);font-size:17px;cursor:pointer;line-height:1}\n.cog.on{background:var(--amber);color:var(--bg);border-color:var(--amber)}\n.tab{display:none}.tab.active{display:block}\nlabel{display:block;color:var(--dim);font-size:11px;letter-spacing:.06em;margin:12px 0 5px}\ntextarea,input,select{width:100%;background:var(--surface-2);border:1px solid var(--line);\n color:var(--prose);font-family:var(--mono);font-size:13px;padding:11px;border-radius:8px}\ntextarea{min-height:150px;resize:vertical;line-height:1.5}\n.row{display:flex;gap:8px}.row>*{flex:1}\nbutton.go{width:100%;margin-top:12px;background:var(--amber);color:var(--bg);border:0;padding:14px;\n border-radius:999px;font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:.08em;\n cursor:pointer}\nbutton.go.ghost{background:var(--surface-2);color:var(--prose);border:1px solid var(--line);font-weight:400}\nbutton.go.danger{background:var(--surface-2);color:var(--red);border:1px solid var(--line);font-weight:400}\nbutton.go:disabled{opacity:.45}\n.out{margin-top:12px;padding:12px;background:var(--surface-2);border:1px solid var(--line);\n border-radius:8px;white-space:pre-wrap;font-size:12px;line-height:1.55;min-height:44px}\n.idle{opacity:.38;pointer-events:none}\naudio{width:100%;margin-top:10px}\n.note{font-size:11px;color:var(--dim);line-height:1.6;margin:6px 0 0}\n.big{font-size:30px;font-weight:300;margin:2px 0;color:var(--prose)}\n.bar{height:4px;background:var(--line);border-radius:3px;overflow:hidden;margin-top:5px}\n.bar i{display:block;height:100%;background:var(--amber)}\ntable{width:100%;border-collapse:collapse;font-size:12px}\ntd,th{text-align:left;padding:7px 5px;border-bottom:1px solid var(--line)}\nth{color:var(--dim);font-weight:400;letter-spacing:.06em}\n.kcard{background:var(--surface-2);border:1px solid var(--line);border-radius:10px;padding:11px;margin-bottom:8px}\n.khead{display:flex;justify-content:space-between;align-items:center;gap:8px}\n.klabel{color:var(--coral);font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.kstatus{font-size:12px;font-weight:700;white-space:nowrap}\n.kkey{color:var(--prose);font-size:12px;margin-top:7px}\n.kwhy{color:var(--dim);font-size:11px;margin-top:3px;line-height:1.5}\n.kdetail{margin-top:8px;padding:8px;background:var(--surface);border:1px solid var(--line);\n border-radius:6px;color:var(--green);font-size:11px;white-space:pre-wrap;line-height:1.5}\n.kacts{display:flex;gap:6px;margin-top:10px}\n.kacts button{flex:1;background:var(--surface);border:1px solid var(--line);color:var(--prose);\n font-family:var(--mono);font-size:11px;padding:10px 4px;border-radius:7px;cursor:pointer}\n.kacts button.gold{color:var(--amber)}\n.kacts button.red{color:var(--red)}\n.kacts button:disabled{opacity:.4}\n.working{color:var(--green)}.busy{color:var(--amber)}.nocredit{color:var(--amber-hi)}\n.refused{color:var(--red)}.unknown{color:var(--grey)}.untested{color:var(--grey)}\n.chip{display:inline-block;background:var(--surface-2);border:1px solid var(--line);\n border-radius:999px;padding:9px 13px;margin:0 5px 5px 0;font-size:11px;color:var(--prose);cursor:pointer}\n.chip.on{border-color:var(--amber);color:var(--amber)}\n.info{background:var(--surface-2);border:1px solid var(--line);border-radius:10px;padding:11px;\n display:flex;gap:10px;align-items:center;margin-top:6px}\n.info .n{flex:1;min-width:0}\n.info .who{font-size:12px;color:var(--coral)}\n.info .v{font-size:11px;color:var(--dim);margin-top:2px}\n.info button{flex:0 0 auto;background:var(--surface);border:1px solid var(--line);color:var(--amber);\n font-family:var(--mono);font-size:11px;padding:11px 14px;border-radius:8px;cursor:pointer}\n/* the spinner. One braille cell, cycled. It is the only thing on the screen\n   that moves, so movement always means the same thing: something is running. */\n.spin{display:inline-block;width:1ch;color:var(--amber)}\n#act{display:flex;gap:9px;align-items:baseline;background:var(--surface-2);\n border:1px solid var(--line);border-radius:999px;padding:9px 14px;margin-bottom:10px;\n font-size:11px;color:var(--dim);letter-spacing:.04em;min-height:36px}\n#act.on{color:var(--prose);border-color:var(--amber)}\n#actmsg{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n</style></head><body><div class="unit">\n\n<div class="top">\n  <div class="tabs">\n    <button class="tab-btn active" data-tab="0">SPEAK</button>\n    <button class="tab-btn" data-tab="1">TRANSCRIBE</button>\n    <button class="tab-btn" data-tab="2">KEYS</button>\n  </div>\n  <button class="cog" id="cog" title="settings">&#9881;</button>\n</div>\n\n<!-- THE ACTIVITY LINE. Always present, in every tab. It is the one place that\n     says what the app is doing, and it says it even when the answer is\n     "nothing", because a line that only appears when something is happening\n     is a line you have to notice appearing. -->\n<div id="act"><span class="spin" id="actspin">●</span><span id="actmsg">ready</span></div>\n\n<!-- SETTINGS. One panel, and what is in it depends on the tab underneath, so\n     the cog always means "the settings for what I am looking at". -->\n<section id="settings" style="display:none">\n  <div id="setSpeak">\n    <label>VOICE 1 &mdash; NAME AND VOICE</label>\n    <div class="row"><input id="n1" value="VIVEKA"><select id="s1"></select></div>\n    <label>VOICE 2 &mdash; NAME AND VOICE</label>\n    <div class="row"><input id="n2" value="MANAN"><select id="s2"></select></div>\n    <label>FIND A VOICE</label>\n    <input id="vq" placeholder="search by name or timbre">\n    <div id="vfacets" style="margin-top:8px"></div>\n    <div id="vlist" style="max-height:44vh;overflow:auto;margin-top:8px"></div>\n  </div>\n  <div id="setListen">\n    <div class="note">Maha Transcribe keeps its own settings in its own panel,\n    behind the cog inside the TRANSCRIBE tab. The keys it uses are the ones on\n    the KEYS tab.</div>\n  </div>\n  <div id="setKeys">\n    <div class="note" id="dep">checking what is installed<span class="spin"></span></div>\n    <div class="note" id="cachenote">counting the cache<span class="spin"></span></div>\n  </div>\n  <div class="note" id="verline"></div>\n</section>\n\n<section class="tab active" id="tab0">\n  <div class="info">\n    <div class="n"><div class="who" id="w1">VIVEKA</div><div class="v" id="d1">Charon &middot; informative</div></div>\n    <button data-hear="1">&#9654; hear</button>\n  </div>\n  <div class="info">\n    <div class="n"><div class="who" id="w2">MANAN</div><div class="v" id="d2">Puck &middot; upbeat</div></div>\n    <button data-hear="2">&#9654; hear</button>\n  </div>\n\n  <label>SCRIPT</label>\n  <textarea id="text" placeholder="&lt;VIVEKA: Amused&gt; Ah. There you are. I was expecting you.\n&lt;MANAN: Anxious: slow&gt; I am trying.\n&lt;VIVEKA: Firm&gt; I know."></textarea>\n  <div class="note">A tag sets who speaks, how, and how fast:\n  &lt;NAME&gt;, &lt;NAME: Weary&gt;, &lt;NAME: Weary: slow&gt;. Put the cursor\n  where you want one and pick below.</div>\n\n  <div class="row">\n    <div><label>INSERT FOR</label><select id="who"></select></div>\n    <div><label>PACE</label><select id="pace"></select></div>\n  </div>\n  <input id="eq" placeholder="search a direction: angry, whisper, teaching">\n  <div id="egroups" style="margin-top:8px"></div>\n  <div id="elist" style="max-height:32vh;overflow:auto;margin-top:8px"></div>\n\n  <button class="go" id="sgo">SPEAK</button>\n  <div class="out idle" id="sout">nothing spoken yet</div>\n  <audio id="player" class="idle" controls></audio>\n</section>\n\n<section class="tab" id="tab1">\n  <iframe id="mt" title="Maha Transcribe"\n    style="width:100%;height:78vh;border:1px solid var(--line);border-radius:10px;background:var(--bg)"></iframe>\n</section>\n\n<section class="tab" id="tab2">\n  <div id="bud" class="idle">reading the ledger<span class="spin"></span></div>\n  <label>ADD ACCOUNTS FROM A FILE</label>\n  <input type="file" id="kf">\n  <div class="note">Any file. A note, a .env, a JSON export, a CSV, a markdown\n  table. It finds the keys, keeps the account names where they are there, and\n  adds only the ones the ring does not already hold.</div>\n  <div class="out idle" id="kimp">nothing imported this session</div>\n  <div class="row">\n    <button class="go ghost" id="testall">TEST ALL</button>\n    <button class="go danger" id="del" disabled>DELETE REFUSED</button>\n  </div>\n  <button class="go ghost" id="undel" disabled>PUT BACK</button>\n  <div id="keys" class="note">no account tested this session. Every row has its\n  own test and delete, so one account can be answered without spending the\n  other twenty.</div>\n</section>\n\n</div>\n<script>\n"use strict";\nvar VERSION = "@@VERSION@@";\nvar ASSUMED = "@@ASSUMED@@";\n\n// ------------------------------------------------------------- activity\n// One line, always on screen, in every tab. Every call goes through here, so\n// there is no path that does work silently: an app that reports the slow\n// things and says nothing about the quick ones teaches you that silence means\n// broken, and then a fast answer looks like a fault.\nvar actTimer = null, actDepth = 0;\nfunction actStart(msg) {\n  actDepth++;\n  var m = document.getElementById("actmsg");\n  var s = document.getElementById("actspin");\n  document.getElementById("act").classList.add("on");\n  m.textContent = msg;\n  if (actTimer) return;\n  var i = 0;\n  actTimer = setInterval(function () {\n    s.textContent = FRAMES[i++ % FRAMES.length];\n  }, 80);\n}\nfunction actStep(msg) {\n  var m = document.getElementById("actmsg");\n  if (m) m.textContent = msg;\n}\nfunction actEnd(msg) {\n  actDepth = Math.max(0, actDepth - 1);\n  if (actDepth > 0) return;\n  if (actTimer) { clearInterval(actTimer); actTimer = null; }\n  document.getElementById("actspin").textContent = "\\u25cf";\n  document.getElementById("act").classList.remove("on");\n  document.getElementById("actmsg").textContent = msg || "ready";\n}\n\n// The header a cross-site request cannot set. Its value does not matter.\nvar H = {"X-Gtt-Local": "1"};\nfunction api(u, o, label) {\n  o = o || {};\n  o.headers = Object.assign({}, H, o.headers || {});\n  if (label) actStart(label);\n  return fetch(u, o).then(function (r) {\n    if (label) actStep("receiving");\n    return r.json();\n  }).then(function (j) {\n    if (label) actEnd();\n    return j;\n  }).catch(function (e) {\n    if (label) actEnd("that did not go through: " + e.message);\n    throw e;\n  });\n}\n\n// Maha Transcribe runs in an iframe and reports its own stages up here, so the\n// line says what the app is doing whichever tab you are looking at.\nwindow.addEventListener("message", function (ev) {\n  if (!ev.data || ev.data.gtt !== "act") return;\n  if (ev.data.done) actEnd(ev.data.msg);\n  else if (actDepth > 0) actStep(ev.data.msg);\n  else actStart(ev.data.msg);\n});\nfunction el(id) { return document.getElementById(id); }\nfunction esc(s) {\n  return String(s).replace(/[&<>"\']/g, function (c) {\n    return {"&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;"}[c];\n  });\n}\n\n// ---------------------------------------------------------------- spinner\n// Braille, one cell, eighty milliseconds. It runs on ANY wait: an app that\n// spins for the slow things and freezes for the quick ones teaches you that a\n// still screen means broken, and then a genuinely quick answer looks broken too.\nvar FRAMES = "\\u280b\\u2819\\u2839\\u2838\\u283c\\u2834\\u2826\\u2827\\u2807\\u280f";\nvar spinners = [];\nfunction spin(node) {\n  if (!node) return function () {};\n  var i = 0;\n  var t = setInterval(function () {\n    node.textContent = FRAMES[i++ % FRAMES.length];\n  }, 80);\n  spinners.push(t);\n  return function stop(txt) {\n    clearInterval(t);\n    node.textContent = txt === undefined ? "" : txt;\n  };\n}\nfunction busy(node, label) {\n  var was = node.innerHTML;\n  var wasDisabled = node.disabled;\n  node.disabled = true;\n  node.innerHTML = (label || "") + \' <span class="sp"></span>\';\n  var stop = spin(node.querySelector(".sp"));\n  return function done(text) {\n    stop();\n    node.innerHTML = text === undefined ? was : text;\n    node.disabled = wasDisabled;\n    if (text !== undefined) setTimeout(function () { node.innerHTML = was; }, 2200);\n  };\n}\nfunction working(node, msg) {\n  node.classList.remove("idle");\n  node.innerHTML = esc(msg || "working") + \' <span class="sp"></span>\';\n  return spin(node.querySelector(".sp"));\n}\n\n// ------------------------------------------------------------------ state\nvar VOICES = [], EMO = [], ROWS = [], STAR = [];\nvar SLOT = {1: {voice: "Charon"}, 2: {voice: "Puck"}};\nvar vfacet = "", efacet = "", tabNow = 0, settingsOpen = false;\ntry { STAR = JSON.parse(localStorage.getItem("gtt_star") || "[]"); } catch (e) { STAR = []; }\ntry {\n  var saved = JSON.parse(localStorage.getItem("gtt_slots") || "null");\n  if (saved) SLOT = saved;\n} catch (e) {}\nfunction saveSlots() { localStorage.setItem("gtt_slots", JSON.stringify(SLOT)); }\n\n// ------------------------------------------------------------------- tabs\nfunction showTab(i) {\n  tabNow = i;\n  var b = document.querySelectorAll(".tab-btn");\n  for (var k = 0; k < b.length; k++) b[k].classList.toggle("active", k === i);\n  for (var k = 0; k < 3; k++) el("tab" + k).classList.toggle("active", k === i && !settingsOpen);\n  el("settings").style.display = settingsOpen ? "block" : "none";\n  el("setSpeak").style.display = i === 0 ? "block" : "none";\n  el("setListen").style.display = i === 1 ? "block" : "none";\n  el("setKeys").style.display = i === 2 ? "block" : "none";\n  if (i === 1 && !el("mt").src) el("mt").src = "/transcribe";\n  if (i === 2) { loadBudget(); checkGrave(); }\n  if (settingsOpen && i === 2) { loadHealth(); loadCache(); }\n}\ndocument.querySelectorAll(".tab-btn").forEach(function (b) {\n  b.addEventListener("click", function () {\n    settingsOpen = false;\n    el("cog").classList.remove("on");\n    showTab(parseInt(b.dataset.tab, 10));\n  });\n});\nel("cog").addEventListener("click", function () {\n  settingsOpen = !settingsOpen;\n  el("cog").classList.toggle("on", settingsOpen);\n  showTab(tabNow);\n});\n\n// ------------------------------------------------------------- catalogues\nfunction loadCatalogues() {\n  var stopB = working(el("bud"), "reading the ledger");\n  Promise.all([api("/api/voices", null, "loading voices"),\n               api("/api/emotions", null, "loading directions")]).then(function (r) {\n    VOICES = r[0];\n    EMO = r[1];\n    var timbres = [];\n    VOICES.forEach(function (v) { if (timbres.indexOf(v.timbre) < 0) timbres.push(v.timbre); });\n    timbres.sort();\n    var f = \'<span class="chip on" data-vf="">all</span><span class="chip" data-vf="*">starred</span>\';\n    timbres.forEach(function (t) { f += \'<span class="chip" data-vf="\' + esc(t) + \'">\' + esc(t) + "</span>"; });\n    el("vfacets").innerHTML = f;\n    var groups = [];\n    EMO.forEach(function (e) { if (groups.indexOf(e.group) < 0) groups.push(e.group); });\n    var g = \'<span class="chip on" data-ef="">all</span>\';\n    groups.forEach(function (x) { g += \'<span class="chip" data-ef="\' + esc(x) + \'">\' + esc(x.toLowerCase()) + "</span>"; });\n    el("egroups").innerHTML = g;\n    ["normal", "slow", "fast", "very slow"].forEach(function (p) {\n      el("pace").add(new Option(p, p));\n    });\n    VOICES.forEach(function (v) {\n      el("s1").add(new Option(v.name + "  " + v.timbre, v.name));\n      el("s2").add(new Option(v.name + "  " + v.timbre, v.name));\n    });\n    el("s1").value = SLOT[1].voice;\n    el("s2").value = SLOT[2].voice;\n    drawVoices();\n    drawEmotions();\n    refreshWho();\n    stopB();\n    loadBudget();\n  });\n}\nfunction timbreOf(name) {\n  for (var i = 0; i < VOICES.length; i++) if (VOICES[i].name === name) return VOICES[i].timbre;\n  return "";\n}\nfunction refreshWho() {\n  var cur = el("who").value;\n  el("who").innerHTML = "";\n  [el("n1").value.trim() || "VOICE 1", el("n2").value.trim() || "VOICE 2"].forEach(function (n) {\n    el("who").add(new Option(n, n));\n  });\n  if (cur) el("who").value = cur;\n  el("w1").textContent = el("n1").value.trim() || "VOICE 1";\n  el("w2").textContent = el("n2").value.trim() || "VOICE 2";\n  el("d1").innerHTML = esc(SLOT[1].voice) + 