  /* Archive now lives inside Settings instead of the main tab bar, so it gets a full width row here instead of a small pill */
  #settingsPanel .tab-btn { width: 100%; display: block; text-align: center; padding: 16px; border-radius: 14px; font-size: 13px; letter-spacing: 0.08em; margin-bottom: 10px; }

  .meter { display: flex; gap: 3px; height: 12px; margin-bottom: 8px; align-items: flex-end; }
  .meter i { flex: 1; background: var(--surface-2); border-radius: 1px; height: 12%; font-style: normal; transition: background 0.3s ease; }
  .meter.idle i { animation: idle-pulse 3s ease-in-out infinite; }
  .meter.busy i { background: var(--amber); animation: meter-bounce 0.9s ease-in-out infinite; }
  .meter.ok i { background: var(--green); height: 70%; animation: none; }
  .meter.err i { background: var(--red); height: 40%; animation: none; }
  .meter i:nth-child(odd) { animation-delay: 0.1s; }
  .meter i:nth-child(3n) { animation-delay: 0.2s; }
  .meter i:nth-child(4n) { animation-delay: 0.3s; }
  .meter i:nth-child(5n) { animation-delay: 0.4s; }
  @keyframes idle-pulse { 0%, 100% { height: 8%; } 50% { height: 18%; } }
  @keyframes meter-bounce { 0%, 100% { height: 20%; } 50% { height: 85%; } }
  @media (prefers-reduced-motion: reduce) { .meter i { animation: none !important; } }

  /* Step one, the file picker, amber and clearly outlined */
  .drop {
    display: block;
    border: 1px solid var(--orange);
    border-radius: 14px;
    padding: 14px;
    text-align: center;
    cursor: pointer;
    color: var(--orange);
    font-weight: 700;
    letter-spacing: 0.05em;
    font-size: 13px;
    margin-bottom: 6px;
    background: rgba(245, 158, 11, 0.08);
  }
  .drop:hover { background: rgba(245, 158, 11, 0.16); }
  .drop.has-file { color: var(--text); border-style: solid; background: var(--surface-2); }
  .drop input { display: none; }

  .row { display: flex; gap: 4px; margin-bottom: 6px; }
  .lang-btn { flex: 1; background: var(--surface-2); border: 1px solid var(--border); color: var(--text-dim); font-family: var(--mono); font-size: 12px; letter-spacing: 0.05em; padding: 15px 4px; border-radius: 999px; cursor: pointer; }
  .lang-btn.active { color: var(--bg); background: var(--amber); border-color: var(--amber); font-weight: 700; }
  .big-choice { flex: 1; background: var(--surface-2); border: 1px solid var(--border); color: var(--text-dim); font-family: var(--mono); font-size: 15px; font-weight: 700; letter-spacing: 0.08em; padding: 20px 6px; border-radius: 14px; cursor: pointer; }
  .big-choice.active { color: var(--bg); background: var(--amber); border-color: var(--amber); }
  .arh-lang-row { margin-bottom: 8px; }
  .claude-effort-row .lang-btn { font-size: 11px; padding: 13px 2px; }

  .transcribe-btn, .rec-btn { width: 100%; padding: 16px; background: var(--amber); color: var(--bg); border: none; border-radius: 14px; font-family: var(--mono); font-weight: 700; letter-spacing: 0.08em; font-size: 13px; cursor: pointer; margin-bottom: 6px; }
  .transcribe-btn:disabled, .rec-btn:disabled { background: var(--surface-2); color: var(--text-dim); cursor: not-allowed; }

  .status { font-size: 12px; color: var(--text-dim); min-height: 34px; line-height: 1.5; margin-bottom: 6px; white-space: pre-wrap; }
  .status.err { color: var(--red); }
  .status.ok { color: var(--green); }

  textarea { width: 100%; min-height: 220px; background: var(--surface-2); border: 1px solid var(--border); border-radius: 12px; color: var(--text); font-family: var(--mono); font-size: 13px; padding: 12px; resize: vertical; margin-bottom: 6px; }
  textarea:focus-visible, .drop:focus-visible, .lang-btn:focus-visible, button:focus-visible, select:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; }

  .copy-btn, .small-btn { background: var(--surface-2); border: 1px solid var(--border); color: var(--text); font-family: var(--mono); font-size: 12px; padding: 11px 16px; border-radius: 999px; cursor: pointer; }
  .copy-btn:hover, .small-btn:hover { border-color: var(--amber); }
  .small-btn.danger:hover { border-color: var(--red); color: var(--red); }

  /* Recorder */
  .rec-clock { font-size: 34px; text-align: center; letter-spacing: 0.06em; margin: 6px 0 2px; font-variant-numeric: tabular-nums; }
  .rec-clock .ms { font-size: 18px; color: var(--text-dim); }
  .rec-state { text-align: center; font-size: 11px; letter-spacing: 0.14em; color: var(--text-dim); margin-bottom: 6px; min-height: 14px; }
  .rec-state.live { color: var(--red); animation: stateBlink 1s steps(1, end) infinite; }
  @keyframes stateBlink { 0%, 50% { opacity: 1; } 50.01%, 100% { opacity: 0.15; } }
  .rec-row { display: flex; gap: 4px; margin-bottom: 6px; }
  .rec-row button { flex: 1; }
  .claude-btn { font-size: 11px; }
  .claude-usage { font-size: 10px; color: var(--text-dim); text-align: center; letter-spacing: 0.03em; margin: 2px 0 8px; font-family: var(--mono); }
  .text-input { width: 100%; box-sizing: border-box; background: var(--surface-2); border: 1px solid var(--border); color: var(--text); font-family: var(--mono); font-size: 13px; padding: 10px 12px; border-radius: 10px; margin-bottom: 10px; }
  .text-input:focus { outline: none; border-color: var(--amber); }
  .rec-btn.stop { background: var(--red); color: var(--bg); }

  /* record (round) + stop, kept as a rounded square (not a full circle) so it still reads as "stop" */
  .rec-controls { display: flex; gap: 20px; justify-content: center; align-items: center; margin-bottom: 6px; }
  .scope { width: 100%; height: 110px; display: block; margin: 4px 0 10px; background: var(--surface-2); border: 1px solid var(--border); border-radius: 14px; }
  .tab-btn.recording { border-color: var(--red); background: rgba(239, 68, 68, 0.14); }
  .tab-btn.recording .hot-r { color: var(--red); font-variant-numeric: tabular-nums; animation: pillBlink 1s steps(1, end) infinite; }
  @keyframes pillBlink { 0%, 50% { opacity: 1; } 50.01%, 100% { opacity: 0.25; } }
  .rec-toggle { width: 96px; height: 96px; border-radius: 50%; border: 1px solid var(--red); background: var(--surface-2); color: var(--red); font-size: 30px; font-weight: 700; letter-spacing: 0.04em; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; font-family: var(--mono); transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease; }
  .rec-toggle.idle { color: var(--red); border-color: var(--red); }
  .rec-toggle.rec { color: var(--red); border-color: var(--red); background: rgba(239, 68, 68, 0.12); }
  .rec-toggle:disabled { opacity: 0.3; cursor: not-allowed; }
  .rec-toggle:hover { background: var(--surface); }
  .rec-cancel-btn { width: 70px; height: 70px; border-radius: 18px; border: 1px solid var(--border); background: var(--surface-2); color: var(--text-dim); font-size: 26px; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; font-family: var(--mono); }
  .rec-cancel-btn:not(:disabled) { color: var(--text-dim); border-color: var(--border); }
  .rec-cancel-btn:hover:not(:disabled) { border-color: var(--red); color: var(--red); background: var(--surface); }
  .rec-cancel-btn:disabled { opacity: 0.3; cursor: not-allowed; animation: none; }

  .rec-settings { margin-top: 4px; }
  .rec-settings .row { margin-bottom: 4px; }
  .rec-settings-label { font-size: 10px; color: var(--text-dim); letter-spacing: 0.12em; font-weight: 700; margin-bottom: 6px; text-align: center; text-transform: uppercase; }

  /* shared language + service block, identical position on REC and TRANSCRIBE */
  .shared-settings { margin-top: 0; border-top: 1px solid var(--border); padding-top: 8px; }
  .shared-settings .row { margin-bottom: 4px; }
  .shared-settings .row:last-child { margin-bottom: 0; }

  /* circular, finger friendly copy button centered on top of the transcript box */
  .transcript-wrap { position: relative; margin-top: 8px; }
  .copy-cp { width: 86px; height: 86px; border-radius: 50%; border: 1px solid var(--amber); background: var(--amber); color: var(--bg); font-family: var(--mono); font-weight: 800; font-size: 26px; letter-spacing: 0.06em; cursor: pointer; display: flex; align-items: center; justify-content: center; flex: 0 0 auto; }
  .copy-cp:hover { filter: brightness(1.08); }
  .copy-cp:active { transform: scale(0.93); }


  /* paste and clear above a text box */
  .box-tools { display: flex; gap: 4px; justify-content: flex-end; margin-bottom: 4px; }
  .box-tools.has-copy { justify-content: space-between; align-items: center; }


  /* Archive */
  .arh-item { border: 1px solid var(--border); border-radius: 12px; padding: 10px; margin-bottom: 6px; background: var(--surface-2); }
  .arh-name { font-size: 12px; margin-bottom: 4px; word-break: break-all; }
  .arh-meta { font-size: 11px; color: var(--text-dim); margin-bottom: 6px; }
  .arh-actions { display: flex; gap: 4px; flex-wrap: wrap; }
  .arh-actions .small-btn { font-size: 11px; padding: 8px 12px; }
  .arh-empty { font-size: 12px; color: var(--text-dim); }

  /* Help */
  .help-body { font-size: 12px; line-height: 1.7; color: var(--text); }
  .help-body h3 { color: var(--amber); font-size: 12px; letter-spacing: 0.1em; margin: 18px 0 6px; }
  .help-body p { margin: 0 0 10px; }

  /* Settings, now its own full tab */
  label.field-label { font-size: 10px; color: var(--text-dim); letter-spacing: 0.09em; font-weight: 700; text-transform: uppercase; display: block; margin-bottom: 4px; }
  .key-picker { display: block; border: 1px dashed var(--border); border-radius: 12px; padding: 12px; font-size: 12px; color: var(--text-dim); text-align: center; cursor: pointer; }
  .key-picker:hover { border-color: var(--amber); color: var(--text); }
  .key-picker.attention { border-color: var(--red); color: var(--red); }
  .key-picker input { display: none; }
  .key-list { font-size: 11px; color: var(--text-dim); line-height: 1.6; margin-top: 6px; }
  .about { font-size: 11px; color: var(--text-dim); margin-top: 8px; line-height: 1.7; }
  .about b { color: var(--cyan); }
  .radio-group { margin-bottom: 6px; }
  .radio-group .field-label { margin-bottom: 4px; }
  .radio-row { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--text); padding: 10px 10px; border: 1px solid var(--border); border-radius: 12px; margin-bottom: 4px; cursor: pointer; background: var(--surface-2); }
  .radio-row:hover { border-color: var(--amber); }
  .radio-row input { accent-color: var(--amber); margin: 0; }
  .radio-row span { word-break: break-all; }

  /* API key ring, one panel per provider */
  .kr-panel { border: 1px solid var(--border); border-radius: 12px; padding: 10px; margin-bottom: 10px; background: var(--surface-2); }
  .kr-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
  .kr-title { font-size: 11px; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--amber-hi, var(--amber)); }
  .kr-count { font-size: 10px; color: var(--text-dim); }
  .kr-empty { font-size: 11px; color: var(--text-dim); padding: 6px 0; }
  .kr-row { display: flex; align-items: center; gap: 8px; padding: 8px 6px; border-bottom: 1px solid var(--border); }
  .kr-row:last-of-type { border-bottom: none; }
  .kr-row input[type=radio] { accent-color: var(--amber); margin: 0; flex: 0 0 auto; }
  .kr-info { flex: 1; min-width: 0; }
  .kr-mask { font-size: 12px; word-break: break-all; }
  .kr-meta { font-size: 10px; color: var(--text-dim); margin-top: 2px; }
  .kr-badge { font-size: 9px; font-weight: 700; letter-spacing: 0.05em; padding: 2px 6px; border-radius: 999px; text-transform: uppercase; display: inline-flex; align-items: center; gap: 3px; }
  .kr-badge .kr-glyph { font-size: 10px; }
  .kr-badge.live { color: var(--green); background: rgba(34, 197, 94, 0.14); }
  .kr-badge.new { color: var(--text-dim); background: var(--surface); }
  .kr-badge.dead { color: var(--red); background: rgba(239, 68, 68, 0.14); }
  .kr-badge.nocredit { color: var(--amber); background: rgba(245, 158, 11, 0.14); }
  .kr-badge.cool { color: var(--amber); background: rgba(245, 158, 11, 0.14); }
  .kr-live { font-size: 10px; color: var(--text-dim); min-height: 14px; margin: 2px 0 4px; }
  .kr-live .kr-glyph.testing { animation: krSpin 1.2s steps(8) infinite; display: inline-block; }
  .kr-live .kr-glyph.live { color: var(--green); }
  .kr-live .kr-glyph.dead { color: var(--red); }
  .kr-live .kr-glyph.nocredit, .kr-live .kr-glyph.cool { color: var(--amber); }
  .kr-live .kr-glyph.unclear { color: var(--text-dim); }
  @keyframes krSpin { from { opacity: 1; } to { opacity: 0.3; } }
  .kr-verbatim { color: var(--green); }
  .kr-row-actions { display: flex; gap: 4px; flex: 0 0 auto; }
  .kr-mini-btn { background: var(--surface); border: 1px solid var(--border); color: var(--text-dim); font-family: var(--mono); font-size: 10px; padding: 6px 8px; border-radius: 999px; cursor: pointer; }
  .kr-mini-btn:hover { border-color: var(--amber); color: var(--amber); }
  .kr-mini-btn.danger:hover { border-color: var(--red); color: var(--red); }
  .kr-import { margin-top: 6px; }
  .kr-import textarea { width: 100%; min-height: 60px; background: var(--bg); border: 1px solid var(--border); border-radius: 8px; color: var(--text); font-family: var(--mono); font-size: 11px; padding: 8px; margin-bottom: 6px; }
  .kr-import-row { display: flex; gap: 4px; }
  .kr-import-row .small-btn { flex: 1; text-align: center; }
</style>
</head>
<body>
<div class="unit">
  <header>
    <div>
      <div class="mode-row" role="group" aria-label="recording mode">
        <button type="button" class="mode-btn" id="modeMulti" data-mode="multi" title="every recording is added under the last one, tap again to start fresh">MULTIPLE</button>
        <button type="button" class="mode-btn" id="modeSingle" data-mode="single" title="every recording replaces the text, tap again to start fresh">SINGLE</button>
      </div>
    </div>
    <button class="gear" id="gearBtn" title="settings" aria-label="settings">&#9881;</button>
  </header>

  <div class="tabs" role="tablist">
    <button class="tab-btn active" id="recPill" data-tab="rec"><span class="hot-r" id="recPillLabel">REC</span></button>
    <button class="tab-btn" data-tab="transcribe">transcribe</button>
  </div>

  <div class="meter idle" id="meter" aria-hidden="true"></div>

  <!-- SHARED SETTINGS, same buttons and position on REC and TRANSCRIBE, always at the top of whichever of those two tabs is open -->
  <div class="shared-settings" id="sharedSettings">
    <div class="row" id="langRow" role="group" aria-label="language">
      <button type="button" class="lang-btn" data-lang="hr">HR</button>
      <button type="button" class="lang-btn" data-lang="en">EN</button>
      <button type="button" class="lang-btn" data-lang="auto">AUTO</button>
    </div>
  </div>

  <!-- REC -->
  <div class="tab active" id="tab-rec">
    <div class="rec-clock" id="recClock">00:00<span class="ms">.0</span></div>
    <div class="rec-state" id="recState"></div>
    <canvas class="scope" id="recScope" width="600" height="150"></canvas>
    <div class="rec-controls">
      <button type="button" class="rec-cancel-btn" id="recCancelBtn" aria-label="cancel" title="cancel and throw this away" disabled>&#10005;</button>
    </div>
    <div class="status" id="recStatus"></div>
    <div class="session-line" id="sessionLine">session empty</div>
    <div class="mode-hint" id="modeHint"></div>
    <button type="button" class="transcribe-btn" id="recTranscribeBtn" disabled>TRANSCRIBE ALL PARTS</button>
  </div>

  <!-- TRANSCRIBE -->
  <div class="tab" id="tab-transcribe">
    <label class="drop" id="drop" for="audioInput">
      <span id="dropLabel">CHOOSE FILE</span>
      <input type="file" id="audioInput" accept="audio/*,video/*">
    </label>

    <button type="button" class="transcribe-btn" id="transcribeBtn" disabled>TRANSCRIBE</button>
    <div class="status" id="status"></div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transcript">paste</button>
      <button type="button" class="copy-cp" id="copyBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transcript">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transcript" placeholder="transcript will appear here" spellcheck="false"></textarea>
    </div>

    <div class="rec-row">
      <button type="button" class="transcribe-btn" id="grammarBtn">GRAMMAR</button>
      <button type="button" class="transcribe-btn" id="reshapeBtn">RE-SHAPE</button>
    </div>
    <div class="status" id="grammarStatus"></div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transcriptCorr">paste</button>
      <button type="button" class="copy-cp" id="copyCorrBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transcriptCorr">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transcriptCorr" placeholder="corrected text will appear here" spellcheck="false"></textarea>
    </div>

    <div class="claude-usage" id="claudeLevelLabel">engagement level</div>
    <div class="row claude-effort-row" id="claudeRow">
      <button type="button" class="lang-btn claude-effort" data-effort="low" id="claude-low">Opus Low</button>
      <button type="button" class="lang-btn claude-effort" data-effort="medium" id="claude-medium">Opus Medium</button>
      <button type="button" class="lang-btn claude-effort" data-effort="high" id="claude-high">Opus High</button>
    </div>
    <div class="status" id="claudeStatus"></div>
    <div class="claude-usage" id="claudeUsage">Claude API  ·  spent $0.0000  ·  left $5.0000</div>
  </div>

  <!-- ARH -->  <!-- ARH -->
  <div class="tab" id="tab-arh">
    <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:8px;">
      <div class="status" id="arhStatus" style="margin:0; min-height:0;">archive</div>
      <button type="button" class="small-btn danger" id="arhDeleteAllBtn">delete all</button>
    </div>
    <div id="arhList"><div class="arh-empty">no recordings yet</div></div>
  </div>

  <!-- TRANSLATE -->
  <div class="tab" id="tab-translate">
    <div class="row" id="transFromRow" role="group" aria-label="from language">
      <button type="button" class="lang-btn tl-from" data-lang="hr">HR</button>
      <button type="button" class="lang-btn tl-from" data-lang="en">EN</button>
      <button type="button" class="lang-btn tl-from" data-lang="auto">AUTO</button>
    </div>
    <div class="box-tools">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transSrc">paste</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transSrc">clear</button>
    </div>
    <textarea id="transSrc" style="min-height:150px;" placeholder="text to translate" spellcheck="false"></textarea>
    <button type="button" class="transcribe-btn" id="translateBtn">TRANSLATE</button>
    <div class="status" id="transStatus"></div>
    <div class="row" id="transToRow" role="group" aria-label="to language">
      <button type="button" class="lang-btn tl-to" data-lang="hr">HR</button>
      <button type="button" class="lang-btn tl-to" data-lang="en">EN</button>
      <button type="button" class="lang-btn tl-to" data-lang="auto">AUTO</button>
    </div>
    <div class="box-tools has-copy">
      <button type="button" class="small-btn" data-boxact="paste" data-target="transOut">paste</button>
      <button type="button" class="copy-cp" id="copyTransBtn" aria-label="copy" title="copy">CP</button>
      <button type="button" class="small-btn" data-boxact="clear" data-target="transOut">clear</button>
    </div>
    <div class="transcript-wrap">
      <textarea id="transOut" placeholder="translation will appear here" spellcheck="false"></textarea>
    </div>
    <label class="field-label">gemini model</label>
    <div class="row" id="transModelList" style="flex-wrap:wrap;"></div>
  </div>

  <!-- QUICK, walkie talkie style, one button, Whisper -->
  <!-- SETTINGS -->
  <div class="tab" id="settingsPanel">
    <div class="rec-settings-label">SETTINGS</div>
    <button class="tab-btn" data-tab="arh">ARCHIVE</button>
    <label class="field-label">engine</label>
    <div class="key-list">
      Gemini, and the model is chosen for you from the ones the account can
      actually reach. There is nothing to pick here and nothing to keep current.
    </div>
    <label class="field-label">api keys</label>
    <div class="key-list">
      The keys are not in this browser. They live in one ring on the server,
      shared with the rest of this app, and the KEYS tab is where they are
      imported, tested and deleted.
    </div>
    <div class="about">
      engine: <b>Gemini, model chosen automatically</b><br>
      keys: <b>the shared ring, in the KEYS tab</b><br>
      file picker: <b>any format ffmpeg can read, optimized before upload</b><br>
      version: <b id="appVersion">v28 (a)</b>
    </div>
  </div>
</div>


<script>
(function () {
  // =========================================================================
  // KEYRING — ported from markoboskoauroville/MAHA_TRANSCRIBE_STREAMLIT
  // ttt/keyring.py. No key is ever hardcoded in this file: every provider's
  // ring lives only in this browser's localStorage, filled in by the person
  // through Settings > api keys, either by pasting a note or picking a file.
  // =========================================================================
  const KR = (() => {
    async function fingerprint(key) {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(key));
      return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('').slice(0, 12);
    }
    function mask(key) {
      const k = (key || '').trim();
      if (k.length <= 10) return k ? k.slice(0, 2) + '\u2026' : '';
      return k.slice(0, 5) + '\u2026' + k.slice(-4);
    }
    function newRing() { return { keys: [], active: 0 }; }

    // first usable key at or after start, wrapping; a rested "cool" key revives itself once its time is up.
    // "nocredit" never self-revives, same as "dead" -- an empty account does not top itself up.
    function pick(ring, start) {
      const keys = ring.keys || []; const n = keys.length;
      if (!n) return null;
      const now = Date.now() / 1000;
      for (let j = 0; j < n; j++) {
        const i = (start + j) % n;
        const k = keys[i];
        if (k.state === 'dead' || k.state === 'nocredit') continue;
        if (k.state === 'cool') {
          if ((k.coolUntil || 0) > now) continue;
          k.state = 'new'; k.lastError = '';
        }
        return i;
      }
      return null;
    }
    function usable(ring) { return (ring.keys || []).some(k => k.state !== 'dead' && k.state !== 'nocredit'); }
    function counts(ring) {
      const now = Date.now() / 1000; let live = 0, dead = 0, cool = 0, nocredit = 0;
      for (const k of (ring.keys || [])) {
        if (k.state === 'dead') dead++;
        else if (k.state === 'nocredit') nocredit++;
        else if (k.state === 'cool' && (k.coolUntil || 0) > now) cool++;
        else live++;
      }
      return { total: (ring.keys || []).length, live, dead, cool, nocredit };
    }

    const URL_RE = /https?:\/\/\S+/g;
    const TOKEN_RE = /[A-Za-z0-9][A-Za-z0-9_.\-]{11,}/g;

    // find every key-shaped token in a piece of messy pasted text, line-aware,
    // and add whichever ones are not already in the ring. Returns how many were new.
    async function importKeys(ring, raw, prefixes, minLen, genericMin) {
      minLen = minLen || 16; genericMin = genericMin || 24; prefixes = prefixes || [];
      const lines = (raw || '').replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
      function tokensOn(line) {
        const cleaned = line.replace(URL_RE, m => prefixes.some(p => m.toLowerCase().includes(p)) ? m : ' ');
        const out = []; let m;
        TOKEN_RE.lastIndex = 0;
        while ((m = TOKEN_RE.exec(cleaned))) {
          const t = m[0].replace(/^[.\-_]+|[.\-_]+$/g, '');
          if (t.length >= 12) out.push(t);
        }
        return out;
      }
      function isPrefixed(tok) {
        const low = tok.toLowerCase();
        return prefixes.length > 0 && prefixes.some(p => low.startsWith(p)) && tok.length >= minLen;
      }
      const perLine = lines.map(tokensOn);
      let found = [];
      perLine.forEach((toks, i) => toks.forEach(tok => { if (isPrefixed(tok)) found.push([tok, i]); }));
      if (!found.length) {
        perLine.forEach((toks, i) => toks.forEach(tok => {
          if (tok.length >= genericMin && /[0-9]/.test(tok) && /[A-Za-z]/.test(tok)) found.push([tok, i]);
        }));
      }
      ring.keys = ring.keys || [];
      const have = new Set(ring.keys.map(k => k.key));
      const seen = new Set(); let added = 0;
      for (const [key, lineIdx] of found) {
        if (seen.has(key) || have.has(key)) continue;
        seen.add(key);
        const label = lineIdx > 0 ? (lines[lineIdx - 1] || '').trim() : '';
        ring.keys.push({
          key, fp: await fingerprint(key), state: 'new', label,
          lastError: '', calls: 0, coolUntil: 0, added: Math.floor(Date.now() / 1000)
        });
        added++;
      }
      return added;
    }

    function markDead(ring, idx, err) { const k = ring.keys[idx]; k.state = 'dead'; k.lastError = err || ''; }
    function markNoCredit(ring, idx, err) { const k = ring.keys[idx]; k.state = 'nocredit'; k.lastError = err || ''; }
    function markCool(ring, idx, err, seconds) {
      const k = ring.keys[idx]; k.state = 'cool'; k.lastError = err || '';
      k.coolUntil = Date.now() / 1000 + (seconds != null ? seconds : 120);
    }
    function markOk(ring, idx) { const k = ring.keys[idx]; k.state = 'new'; k.lastError = ''; k.calls = (k.calls || 0) + 1; }
    function reviveAll(ring) {
      let n = 0;
      for (const k of (ring.keys || [])) {
        if (k.state === 'dead' || k.state === 'nocredit' || k.state === 'cool') { k.state = 'new'; k.lastError = ''; k.coolUntil = 0; n++; }
      }
      return n;
    }
    function reviveOne(ring, idx) { const k = ring.keys[idx]; if (!k) return; k.state = 'new'; k.lastError = ''; k.coolUntil = 0; }
    function deleteOne(ring, idx) {
      ring.keys.splice(idx, 1);
      if (ring.active >= ring.keys.length) ring.active = 0;
    }

    // walk the ring until a key works. attempt(keyStr) resolves to
    // {result, err, kind, wait} where kind is 'ok' | 'dead' | 'nocredit' | 'cool' | 'soft' | 'canceled'.
    // a 'soft' failure is nobody's fault, so it stops immediately instead of burning every key.
    async function rotate(ring, attempt) {
      const keys = ring.keys || []; const n = keys.length;
      if (!n) return { result: null, err: 'no keys yet, add one in settings' };
      let idx = (ring.active || 0) % n;
      let last = '';
      for (let tries = 0; tries < n; tries++) {
        const i = pick(ring, idx);
        if (i === null) break;
        const key = keys[i].key;
        const got = await attempt(key);
        if (got.kind === 'canceled') return { result: null, err: null, canceled: true };
        if (got.kind === 'ok') {
          markOk(ring, i);
          ring.active = i;
          return { result: got.result, err: null, keyIndex: i };
        }
        last = got.err || 'unknown error';
        if (got.kind === 'dead') markDead(ring, i, got.err);
        else if (got.kind === 'nocredit') markNoCredit(ring, i, got.err);
        else if (got.kind === 'cool') markCool(ring, i, got.err, got.wait);
        else return { result: null, err: got.err };  // soft: not the key's fault, stop here
        idx = (i + 1) % n;
      }
      return { result: null, err: 'all ' + n + ' key(s) unavailable. last: ' + last };
    }

    return { fingerprint, mask, newRing, pick, usable, counts, importKeys, markDead, markNoCredit, markCool, markOk, reviveAll, reviveOne, deleteOne, rotate };
  })();

  // ---- one shared classifier for every provider, the table from quota-and-fallback.md §3 ----
  function krClassify(status, bodyText, headers) {
    const lower = (bodyText || '').toLowerCase();
    if (status === 403 && lower.includes('1010')) return { kind: 'soft', err: 'blocked by cloudflare (1010), not a key problem' };
    let wait = null;
    const ra = headers && headers.get ? headers.get('retry-after') : null;
    if (ra) { const n = parseFloat(ra); if (isFinite(n)) wait = n; }
    if (wait == null && headers && headers.get) {
      for (const h of ['x-ratelimit-reset-requests', 'x-ratelimit-reset-tokens', 'x-ratelimit-reset']) {
        const v = headers.get(h);
        if (v) { const n = parseFloat(v); if (isFinite(n)) { wait = n; break; } }
      }
    }
    const hasRetryHint = wait != null || /retrydelay|retry-after|try again in/.test(lower);
    const creditWords = /zero_credits|e0300|credit balance|insufficient|quota exceeded|out of credits|payment required|billing|depleted|prepayment/;
    // 401/403 is REJECTED: the key itself is bad, revoked, or invalid.
    // credit words under 400/429 is NO CREDIT: the key is real and the account
    // is alive, it simply cannot afford the work right now — a different fact
    // with a different fix (top up), so it gets its own state rather than
    // being buried alongside a genuinely dead key. See modules/keyring.md §2d.
    if (status === 401 || status === 403) return { kind: 'dead', err: 'HTTP ' + status + (bodyText ? ': ' + bodyText.slice(0, 160) : '') };
    if (status === 429) {
      if (!hasRetryHint && creditWords.test(lower)) return { kind: 'nocredit', err: 'out of credit' };
      return { kind: 'cool', err: 'rate limited', wait: wait != null ? Math.min(3600, Math.max(1, wait)) : 60 };
    }
    if (status === 400) {
      if (creditWords.test(lower)) return { kind: 'nocredit', err: 'out of credit' };
      return { kind: 'soft', err: 'bad request: ' + (bodyText || '').slice(0, 160) };
    }
    if (status === 404) return { kind: 'soft', err: 'wrong endpoint (404)' };
    if (status >= 500) return { kind: 'soft', err: 'provider error ' + status };
    return { kind: 'soft', err: 'HTTP ' + status };
  }

  // ---- per-provider rings, loaded from and saved to this browser only ----
  const KR_PROVIDERS = {
    claude:   { label: 'claude',                storageKey: 'maha_ring_claude',  prefixes: ['sk-ant-'] },
    gemini:   { label: 'gemini',                 storageKey: 'maha_ring_gemini',  prefixes: ['aq.'] },
    groq:     { label: 'groq (archive titles)',  storageKey: 'maha_ring_groq',    prefixes: ['gsk_'] },
