    if (!aaiModelList) return;
    const cur = getAaiModel();
    aaiModelList.innerHTML = AAI_MODELS.map(m =>
      '<button type="button" class="lang-btn aai-model' + (m === cur ? ' active' : '') + '" data-model="' + m + '">' + m + '</button>'
    ).join('');
